/**
 * Module: reconcileEvents
 * Exports the function reconcileEvents that merges two arrays of event objects
 * while preserving the order of first appearance and ensuring the latest value
 * for each unique id. Neither the input arrays nor the contained objects are
 * mutated.
 *
 * Key behaviors:
 *   - Iterates over `current` first to establish initial order.
 *   - Then iterates over `incoming`, updating existing entries or appending
 *     new ones while maintaining the original order of previously seen ids.
 *   - For duplicate ids within a single array, the last occurrence wins.
 *   - Returns a new plain object for each merged event to avoid accidental
 *     mutation of the original data.
 *
 * @param {Array<object>} current   Array of event objects with an `id` property.
 * @param {Array<object>} incoming Array of event objects with an `id` property.
 * @returns {Array<object>} A new array with merged events respecting first‑seen
 *                          order and latest values.
 */
export function reconcileEvents(current, incoming) {
  // Map to track the index of each id as it appears in the result.
  const indexMap = new Map();

  // Result array that will preserve order.
  const result = [];

  // Helper to process an object: update map if new, replace if existing.
  const process = (obj) => {
    const id = obj.id;
    const position = indexMap.get(id);
    if (position === undefined) {
      // First time we see this id: push a shallow copy and record index.
      indexMap.set(id, result.length);
      result.push({ ...obj });
    } else {
      // Update the existing entry with a fresh copy of the incoming object.
      result[position] = { ...obj };
    }
  };

  // Process current events first (preserves their original order).
  current.forEach(process);

  // Process incoming events (may update or append).
  incoming.forEach(process);

  return result;
}

/**
 * Summary:
 *   The reconcileEvents function merges two event arrays by id, ensuring that:
 *   • The first occurrence of each id determines its position.
 *   • Later occurrences (both in `current` and `incoming`) replace the earlier
 *     one with their data.
 *   • The output order matches the order in which ids were first seen.
 *   • No mutation of inputs or contained objects occurs; all data is deep
 *     copied where necessary.
 *
 * Handoff:
 *   An independent verifier should confirm that:
 *   1. For each test case the returned array matches the expected result.
 *   2. The original `current` and `incoming` arrays remain unchanged (including
 *      object identity when frozen).
 *   3. The order of first‑seen ids is preserved, even when later updates
 *      modify values at their original positions.
